import numpy as np
from scipy.optimize import least_squares
def fit(f,n,trials=12):
    best=None
    for s in range(trials):
        p0=np.random.RandomState(s).uniform(0.1,3,n)
        try:
            r=least_squares(lambda p: np.nan_to_num(f(p)-dP_dt,nan=1e3,posinf=1e3,neginf=-1e3),p0,max_nfev=500)
            if best is None or r.cost<best.cost: best=r
        except Exception as e:
            pass
    if best is None: return None
    return round(float(np.mean((f(best.x)-dP_dt)**2)/np.var(dP_dt)),6), best.x.round(3)
